def min_knight_moves(x, y):
    dirs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
    q = deque([(0, 0, 0)])  # (x, y, moves)
    visited = {(0, 0)}

    while q:
        cx, cy, moves = q.popleft()
        if (cx, cy) == (x, y):
            return moves

        for dx, dy in dirs:
            nx, ny = cx + dx, cy + dy
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny, moves + 1))

    return -1

def rotting_oranges(grid):
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    queue = deque()
    fresh = 0

    # Enqueue all rotten, count fresh
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "R": queue.append((r, c))
            elif grid[r][c] == "F": fresh += 1

    minutes = 0
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]

    while queue and fresh > 0:
        minutes += 1
        for _ in range(len(queue)):  # level-by-level
            r, c = queue.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]=="F":
                    grid[nr][nc] = "R"
                    fresh -= 1
                    queue.append((nr, nc))

    return minutes if fresh == 0 else -1

