def updateMatrix(mat):
    rows, cols = len(mat), len(mat[0])
    dist = [[-1] * cols for _ in range(rows)]
    q = deque()

    # Start BFS from all 0s
    for r in range(rows):
        for c in range(cols):
            if mat[r][c] == 0:
                dist[r][c] = 0
                q.append((r, c))

    # Expand level-by-level
    while q:
        r, c = q.popleft()
        for dr, dc in [(0,1),(1,0),(0,-1),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))
    return dist

def bus_routes(routes, source, target):
    if source == target:
        return 0
    # stop -> [route indices]
    bus_stops = {}
    for i, route in enumerate(routes):
        for stop in route:
            bus_stops.setdefault(stop, []).append(i)

    visited = set()
    queue = deque([(r, 1) for r in bus_stops.get(source, [])])
    visited.update(bus_stops.get(source, []))

    while queue:
        bus, count = queue.popleft()
        if target in routes[bus]:
            return count
        for stop in routes[bus]:
            for conn in bus_stops.get(stop, []):
                if conn not in visited:
                    queue.append((conn, count + 1))
                    visited.add(conn)
    return -1

def letterCombinations(digits):
    phone = {"2":"abc", "3":"def", "4":"ghi",
             "5":"jkl", "6":"mno", "7":"pqrs",
             "8":"tuv", "9":"wxyz"}
    result = []
    def backtrack(path, idx):
        if idx == len(digits):
            result.append(path)
            return
        for letter in phone[digits[idx]]:
            backtrack(path + letter, idx + 1)
    if digits:
        backtrack("", 0)
    return result

def generateParenthesis(n):
    res = []
    def dfs(s, open_count, close_count):
        if len(s) == 2 * n:
            res.append(s)
            return
        if open_count < n:
            dfs(s + '(', open_count + 1, close_count)
        if close_count < open_count:
            dfs(s + ')', open_count, close_count + 1)
    dfs("", 0, 0)
    return res

def combinationSum(candidates, target):
    def backtrack(start, combo, remain):
        if remain == 0:
            result.append(list(combo))
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remain:
                return  # prune
            combo.append(candidates[i])
            backtrack(i, combo, remain - candidates[i])  # same i: reuse
            combo.pop()

    candidates.sort()
    result = []
    backtrack(0, [], target)
    return result

def partition(s):
    result = []
    current = []

    def is_palindrome(left, right):
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    def backtrack(start):
        if start == len(s):
            result.append(current[:])
            return
        for end in range(start, len(s)):
            if is_palindrome(start, end):
                current.append(s[start:end+1])
                backtrack(end + 1)
                current.pop()

    backtrack(0)
    return result

def topological_sort(adj_list, n):
    from collections import deque

    # calculate indegree
    indegree = [0] * n
    for u in adj_list:
        for v in adj_list[u]:
            indegree[v] += 1

    # start with nodes that have no dependencies
    queue = deque([u for u in range(n) if indegree[u] == 0])
    order = []

    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj_list.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    return order if len(order) == n else []

def dijkstra(graph, source):
    dist = {source: 0}
    heap = [(0, source)]

    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, float('inf')):
            continue

        for neighbor, weight in graph.get(node, []):
            new = d + weight
            if new < dist.get(neighbor, float('inf')):
                dist[neighbor] = new
                heapq.heappush(heap, (new, neighbor))

    return dist

def network_delay_time(times, n, k):
    from heapq import heappop, heappush
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))

    distances = {k: 0}
    heap = [(0, k)]

    while heap:
        dist, node = heappop(heap)
        if dist > distances.get(node, float('inf')):
            continue
        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < distances.get(neighbor, float('inf')):
                distances[neighbor] = new_dist
                heappush(heap, (new_dist, neighbor))

    return -1 if len(distances) != n else max(distances.values())

