from collections import defaultdict

def findCheapestPrice(n, flights, src, dst, k):
    graph = defaultdict(list)
    for u, v, price in flights:
        graph[u].append((v, price))

    heap = [(0, src, 0)]  # (cost, city, stops)
    best = {}  # Track best cost per (city, stops)

    while heap:
        cost, city, stops = heappop(heap)

        if city == dst:
            return cost
        if stops > k:
            continue
        if (city, stops) in best and best[(city, stops)] <= cost:
            continue
        best[(city, stops)] = cost

        for neighbor, price in graph[city]:
            heappush(heap, (cost + price, neighbor, stops + 1))

    return -1

import heapq

def minimum_effort_path(heights):
    rows, cols = len(heights), len(heights[0])
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]  # (effort, row, col)

    while heap:
        effort, r, c = heapq.heappop(heap)
        if r == rows - 1 and c == cols - 1:
            return effort
        if effort > dist[r][c]:
            continue
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                diff = abs(heights[nr][nc] - heights[r][c])
                new_effort = max(effort, diff)
                if new_effort < dist[nr][nc]:
                    dist[nr][nc] = new_effort
                    heapq.heappush(heap, (new_effort, nr, nc))
    return dist[rows - 1][cols - 1]

def find_the_city(n, edges, threshold):
    # Init: diagonal=0, edges=weight, missing=∞
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = dist[v][u] = w

    # Floyd-Warshall: k outer!
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Count reachable; <= ensures highest index wins ties
    result, min_count = 0, n
    for city in range(n):
        count = sum(1 for j in range(n) if city != j and dist[city][j] <= threshold)
        if count <= min_count:
            min_count, result = count, city
    return result

def climbStairs(n: int) -> int:
    """Ways to climb n stairs (1 or 2 steps)."""
    if n <= 1:
        return 1
    prev2, prev1 = 1, 1
    for i in range(2, n + 1):
        curr = prev1 + prev2
        prev2, prev1 = prev1, curr
    return prev1

def rob(treasure):
    if not treasure:
        return 0
    prev, curr = 0, treasure[0]
    for i in range(2, len(treasure) + 1):
        take = prev + treasure[i - 1]
        skip = curr
        prev, curr = curr, max(take, skip)
    return curr

def count_bits(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)
    return dp

def num_decodings(s):
    if not s or s[0] == '0':
        return 0
    prev2, prev1 = 1, 1
    for i in range(2, len(s) + 1):
        curr = 0
        if s[i-1] != '0':
            curr += prev1
        if 10 <= int(s[i-2:i]) <= 26:
            curr += prev2
        prev2, prev1 = prev1, curr
    return prev1

def unique_paths(m: int, n: int) -> int:
    dp = [[1] * n for _ in range(m)]
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[m-1][n-1]

def maximal_square(matrix):
    if not matrix:
        return 0
    r, c = len(matrix), len(matrix[0])
    dp = [[0] * (c + 1) for _ in range(r + 1)]
    max_side = 0

    for i in range(1, r + 1):
        for j in range(1, c + 1):
            if matrix[i - 1][j - 1] == 1:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
                max_side = max(max_side, dp[i][j])

    return max_side * max_side

from bisect import bisect_left

def lis_length(nums):
    tails = []
    for num in nums:
        pos = bisect_left(tails, num)
        if pos == len(tails):
            tails.append(num)
        else:
            tails[pos] = num
    return len(tails)

def wordBreak(s, wordDict):
    wordSet = set(wordDict)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in wordSet:
                dp[i] = True
                break

    return dp[len(s)]

def min_cost(costs):
    if not costs:
        return 0

    r, b, g = costs[0]

    for i in range(1, len(costs)):
        r, b, g = (
            costs[i][0] + min(b, g),
            costs[i][1] + min(r, g),
            costs[i][2] + min(r, b)
        )

    return min(r, b, g)

def min_cost_ii(costs):
    prev = costs[0][:]
    for i in range(1, len(costs)):
        # Find min1, min2, min1_idx
        min1 = min2 = float('inf')
        min1_idx = -1
        for j, val in enumerate(prev):
            if val < min1:
                min2, min1, min1_idx = min1, val, j
            elif val < min2:
                min2 = val
        # Build curr row
        curr = [costs[i][j] + (min2 if j == min1_idx else min1)
                for j in range(len(costs[0]))]
        prev = curr
    return min(prev)

def min_window_subsequence(s1, s2):
    m, n = len(s1), len(s2)
    dp = [-1] * n
    result = ""
    min_len = float('inf')

    for i in range(m):
        # Reverse to preserve dp[j-1]
        for j in range(n - 1, -1, -1):
            if s1[i] == s2[j]:
                dp[j] = i if j == 0 else dp[j - 1]

        if dp[n - 1] != -1:
            start = dp[n - 1]
            length = i - start + 1
            if length < min_len:
                min_len = length
                result = s1[start:i + 1]

    return result

def canCompleteCircuit(gas, cost):
    if sum(gas) < sum(cost):
        return -1

    start, fuel = 0, 0
    for i in range(len(gas)):
        if fuel + gas[i] - cost[i] < 0:
            start, fuel = i + 1, 0
        else:
            fuel += gas[i] - cost[i]
    return start

def canJump(nums):
    max_reach = 0
    for i in range(len(nums)):
        if i > max_reach:
            return False
        max_reach = max(max_reach, i + nums[i])
    return True

def jump(nums):
    jumps = 0
    current_end = 0
    farthest = 0

    for i in range(len(nums) - 1):
        farthest = max(farthest, i + nums[i])

        if i == current_end:
            jumps += 1
            current_end = farthest

    return jumps

def partitionLabels(s):
    last = {c: i for i, c in enumerate(s)}
    result, start, end = [], 0, 0

    for i, c in enumerate(s):
        end = max(end, last[c])
        if i == end:
            result.append(i - start + 1)
            start = i + 1

    return result

