class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def starts_with(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def startsWith(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def delete(self, word):
        def _delete(node, i):
            if i == len(word):
                node.is_end = False
                return len(node.children) == 0
            char = word[i]
            if char not in node.children:
                return False
            should_delete = _delete(node.children[char], i + 1)
            if should_delete:
                del node.children[char]
            return not node.is_end and len(node.children) == 0
        _delete(self.root, 0)

def prefix_match(self, prefix):
    # Walk to prefix node
    node = self.root
    for char in prefix:
        if char not in node.children:
            return []
        node = node.children[char]

    # DFS to collect all words
    result = []
    def dfs(node, word):
        if node.isEndOfWord:
            result.append(word)
        for char, child in node.children.items():
            dfs(child, word + char)

    dfs(node, prefix)
    return result

def build_prefix(arr):
    prefix = [0] * (len(arr) + 1)
    for i in range(1, len(arr) + 1):
        prefix[i] = prefix[i - 1] + arr[i - 1]
    return prefix

def range_sum(prefix, left, right):
    return prefix[right + 1] - prefix[left]

def count_vowels(word, queries):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    prefix = [0] * (len(word) + 1)

    # Build prefix sum
    for i in range(1, len(word) + 1):
        prefix[i] = prefix[i-1] + (1 if word[i-1] in vowels else 0)

    # Answer queries in O(1)
    return [prefix[r+1] - prefix[l] for l, r in queries]

from collections import deque

def spiral_order(matrix):
    matrix = deque(deque(row) for row in matrix)
    result = []

    while matrix:
        result.extend(matrix.popleft())  # top row

        if matrix and matrix[0]:
            for row in matrix:
                result.append(row.pop())  # right column

        if matrix:
            result.extend(reversed(matrix.pop()))  # bottom row

        if matrix and matrix[0]:
            for row in reversed(matrix):
                result.append(row.popleft())  # left column

    return result

def rotate_image(matrix):
    n = len(matrix)
    # Transpose
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Reverse each row
    for i in range(n):
        matrix[i] = matrix[i][::-1]
    return matrix

def setZeroes(matrix):
    rows, cols = len(matrix), len(matrix[0])

    # Save first row/col state
    first_row_zero = any(matrix[0][j] == 0 for j in range(cols))
    first_col_zero = any(matrix[i][0] == 0 for i in range(rows))

    # Mark using first row/col
    for i in range(1, rows):
        for j in range(1, cols):
            if matrix[i][j] == 0:
                matrix[i][0] = matrix[0][j] = 0

    # Zero inner matrix
    for i in range(1, rows):
        for j in range(1, cols):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0

    # Zero first row/col last
    if first_row_zero:
        matrix[0] = [0] * cols
    if first_col_zero:
        for i in range(rows):
            matrix[i][0] = 0
